components.css:
.ds-tab-bar {





  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  width: min(352px, calc(100% - 32px));
  min-height: 64px;
  padding: 5px;
  border: 1px solid rgb(255 255 255 / 65%);
  border-radius: 34px;
  background: rgb(248 249 246 / 72%);
  -webkit-backdrop-filter: blur(24px) saturate(150%);
  backdrop-filter: blur(24px) saturate(150%);
  box-shadow: 0 4px 20px rgb(18 36 27 / 12%), inset 0 1px 0 rgb(255 255 255 / 70%);
  font-family: -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
}

.ds-tab-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-width: 0;
  min-height: 52px;
  padding: 3px 6px;
  border-radius: 28px;
  color: #505651;
  font-size: 11px;
  line-height: 13px;
  font-weight: 600;
  letter-spacing: 0;
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 160ms ease-out, color 160ms ease-out;
}

.ds-tab-icon { flex: none; }
.ds-tab-item[aria-current="page"] {
  color: var(--green, #193e32);
  background: rgb(30 55 43 / 9%);
}
.ds-tab-item:active { background: rgb(30 55 43 / 14%); }
.ds-tab-item:focus-visible { outline: 2px solid var(--green, #193e32); outline-offset: -2px; }

@media (hover: hover) {
  .ds-tab-item:hover { background: rgb(30 55 43 / 7%); }
  .ds-tab-item[aria-current="page"]:hover { background: rgb(30 55 43 / 12%); }
}

@media (min-width: 761px), (orientation: landscape) and (max-height: 500px) {
  .ds-tab-bar { width: 424px; min-height: 52px; padding: 3px;  }
  .ds-tab-item { flex-direction: row; gap: 7px; min-height: 44px; font-size: 13px; line-height: 18px; }
  .ds-tab-icon { width: 20px; height: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .ds-tab-item { transition: none; }
}
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) {
  .ds-tab-bar { background: #f8f9f6; -webkit-backdrop-filter: none; backdrop-filter: none; border-color: #a1aaa1; }
  .ds-tab-item { color: #343c35; }
  .ds-tab-item[aria-current="page"] { background: #dce3da; }
}
@supports not (backdrop-filter: blur(1px)) {
  .ds-tab-bar { background: #f8f9f6; }
}
